// Pedidos por segundo que genera el sondeo: personas con la pantalla abierta / segundos entre pedidos
const casos = [
  { que: "Sala de iglesia, 60 personas, cada 2 s", cada: 2, gente: 60 },
  { que: "Sala grande, 500 personas, cada 2 s", cada: 2, gente: 500 },
  { que: "Inicio con 1000 personas, cada 45 s", cada: 45, gente: 1000 },
];
for (const c of casos) {
  const porSeg = c.gente / c.cada;
  console.log(`${c.que}: ${porSeg.toFixed(1)} pedidos/s (${Math.round(porSeg * 60)} por minuto)`);
}
// Una sala de 60 personas que dura 20 minutos
console.log("Sala de 60 personas durante 20 min:", 60 * (20 * 60) / 2, "pedidos en total");
// Con push: un aviso por evento, sin importar cuánta gente esté mirando
console.log("Push: 300 eventos por hora ->", (300 / 3600).toFixed(2), "avisos por segundo");
